import { useCmsDatabase } from "@/wab/client/components/cms/cms-contexts";
import {
  DefaultCmsSchemaPageProps,
  PlasmicCmsSchemaPage,
} from "@/wab/client/plasmic/plasmic_kit_cms/PlasmicCmsSchemaPage";
import { Redirect } from "@/wab/client/route/Redirect";
import { Switch, switchCase, switchDefault } from "@/wab/client/route/Switch";
import { useMatchedRoute } from "@/wab/client/route/useMatchedRoute";
import { APP_ROUTES } from "@/wab/shared/route/app-routes";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import * as React from "react";
export type CmsSchemaPageProps = DefaultCmsSchemaPageProps;

function CmsSchemaPage_(
  props: CmsSchemaPageProps,
  ref: HTMLElementRefOf<"div">
) {
  const m = useMatchedRoute(APP_ROUTES.cmsSchemaRoot);
  const database = useCmsDatabase(m?.pathParams.databaseId);
  if (!m || !database) {
    return null;
  }

  // Sort to make archived tables last on the list
  // Sorting by id to make it stable.
  const tables = database.tables.sort((a, b) =>
    a.isArchived == b.isArchived
      ? b.id.localeCompare(a.id)
      : a.isArchived
      ? 1
      : -1
  );
  return (
    <Switch
      cases={[
        switchCase({
          route: APP_ROUTES.cmsModelSchema,
          render: ({ databaseId, tableId }) => {
            if (!tables.find((t) => t.id === tableId)) {
              return (
                <Redirect to={APP_ROUTES.cmsSchemaRoot.fill({ databaseId })} />
              );
            } else {
              return (
                <PlasmicCmsSchemaPage
                  root={{ ref }}
                  {...props}
                  cmsModelDetails={{ key: tableId }}
                />
              );
            }
          },
        }),
        switchCase({
          route: APP_ROUTES.cmsSchemaRoot,
          render: (pathParams) => {
            if (tables.length > 0) {
              return (
                <Redirect
                  to={APP_ROUTES.cmsModelSchema.fill({
                    ...pathParams,
                    tableId: tables[0].id,
                  })}
                />
              );
            } else {
              return (
                <PlasmicCmsSchemaPage
                  root={{ ref }}
                  {...props}
                  noModels={true}
                />
              );
            }
          },
        }),
        switchDefault({ render: () => null }),
      ]}
    />
  );
}

const CmsSchemaPage = React.forwardRef(CmsSchemaPage_);
export default CmsSchemaPage;
